/**
 * Outreach Executor Agent — Step 3 of 4 in DWS Outreach Pipeline
 *
 * Delivers an approved outreach thread via email (SES SMTP) or queues it
 * for LinkedIn delivery (human copy-paste from daily digest).
 *
 * Email: uses src/utils/send-email.ts (Amazon SES SMTP, eu-north-1).
 * LinkedIn: writes draft to outreach_activities with outcome=queued.
 *   LinkedIn DM API requires MDP partner status — not available programmatically.
 *   Human copies from daily digest generated by src/outreach/daily-digest.ts.
 *
 * REQUIRES: approvedBy field — enforces Tier 2 human approval gate.
 *
 * Input:  { threadId, toEmail, toName, channel, approvedBy }
 * Output: delivery receipt + thread status
 *
 * Tier: 2 (outbound communication — human must set approvedBy before sending)
 */

import logger from '../utils/logger.js';
import { BaseAgent } from './base.agent.js';
import { sendEmail } from '../utils/send-email.js';
import type { AgentContext, AgentResponse } from './types.js';

const FROM_EMAIL = 'risto@onelifetime.world';
const FROM_NAME = 'Risto at DWS';

// ============ INPUT / OUTPUT TYPES ============

interface ExecutorInput {
  threadId: string;
  toEmail: string;
  toName: string;
  channel: 'email' | 'linkedin';
  approvedBy: string;
}

interface ThreadRow {
  id: string;
  email_subject: string;
  email_body: string;
  linkedin_message: string | null;
  org_domain: string;
  status: string;
}

// ============ AGENT IMPLEMENTATION ============

export class OutreachExecutorAgent extends BaseAgent {
  constructor() {
    super({
      name: 'outreach-executor',
      description:
        'Delivers approved outreach threads via email (Amazon SES) or queues LinkedIn drafts for human delivery. Requires explicit human approval (approvedBy) before sending.',
      capabilities: [
        'email-delivery',
        'linkedin-queue',
        'outreach-execution',
        'b2b-outreach',
        'ses-smtp',
      ],
      model: 'placeholder',
      modelTier: 'lite',
    });
  }

  async execute(context: AgentContext, input: Record<string, unknown>): Promise<AgentResponse> {
    const startTime = Date.now();

    await this.logExecution({
      agent_name: this.config.name,
      user_id: context.userId,
      org_id: context.orgId,
      session_id: context.sessionId,
      project_id: context.projectId,
      input,
      output: null,
      status: 'started',
      duration_ms: 0,
      created_at: new Date().toISOString(),
    });

    try {
      const validated = this.validateInput(input);

      // Fetch thread from Supabase
      const thread = await this.fetchThread(validated.threadId);
      if (!thread) {
        throw new Error(`Thread ${validated.threadId} not found in outreach_threads`);
      }

      let deliveryResult: { ok: boolean; detail: string };

      if (validated.channel === 'email') {
        deliveryResult = await this.sendEmailChannel(thread, validated);
      } else {
        deliveryResult = await this.queueLinkedInChannel(thread, validated, context);
      }

      // Update thread status
      await this.updateThreadStatus(
        validated.threadId,
        validated.channel === 'email' ? 'contacted' : 'intro_requested',
      );

      // Log activity
      await this.logActivity(validated, thread, deliveryResult, context);

      const response: AgentResponse = {
        agentName: this.config.name,
        result: {
          threadId: validated.threadId,
          channel: validated.channel,
          ok: deliveryResult.ok,
          detail: deliveryResult.detail,
          approvedBy: validated.approvedBy,
        },
        confidence: deliveryResult.ok ? 0.95 : 0.3,
        reasoning: deliveryResult.ok
          ? `${validated.channel === 'email' ? 'Email sent via Amazon SES' : 'LinkedIn draft queued for human delivery'} for thread ${validated.threadId}. Approved by ${validated.approvedBy}.`
          : `Delivery failed: ${deliveryResult.detail}`,
        recommendations: deliveryResult.ok
          ? [
              'Monitor for reply in Supabase outreach_threads (status: responded)',
              'Follow up in 3–5 business days if no reply',
              `For LinkedIn: copy message from daily digest at /api/v1/outreach/digest`,
            ]
          : [
              'Retry after fixing the error',
              'Check SMTP credentials in SMTP_HOST/SMTP_USER/SMTP_PASS env vars',
            ],
        metadata: {
          durationMs: Date.now() - startTime,
          model: this.config.model,
          channel: validated.channel,
          threadId: validated.threadId,
          approvedBy: validated.approvedBy,
        },
      };

      await this.logExecution({
        agent_name: this.config.name,
        user_id: context.userId,
        org_id: context.orgId,
        session_id: context.sessionId,
        project_id: context.projectId,
        input,
        output: response,
        status: 'completed',
        duration_ms: Date.now() - startTime,
        created_at: new Date().toISOString(),
      });

      return response;
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      const durationMs = Date.now() - startTime;
      logger.error('Outreach executor failed', { agent: this.config.name, error: errorMessage });

      await this.logExecution({
        agent_name: this.config.name,
        user_id: context.userId,
        org_id: context.orgId,
        session_id: context.sessionId,
        project_id: context.projectId,
        input,
        output: null,
        status: 'error',
        error_message: errorMessage,
        duration_ms: durationMs,
        created_at: new Date().toISOString(),
      });

      return {
        agentName: this.config.name,
        result: { error: errorMessage },
        confidence: 0,
        reasoning: `Executor failed: ${errorMessage}`,
        recommendations: [
          'Verify threadId exists in outreach_threads',
          'Ensure approvedBy is set (required for Tier 2)',
        ],
        metadata: { durationMs, model: this.config.model },
      };
    }
  }

  // ============ PRIVATE METHODS ============

  private validateInput(input: Record<string, unknown>): ExecutorInput {
    const threadId = typeof input.threadId === 'string' ? input.threadId.trim() : '';
    if (!threadId) throw new Error('threadId is required');

    const approvedBy = typeof input.approvedBy === 'string' ? input.approvedBy.trim() : '';
    if (!approvedBy)
      throw new Error('approvedBy is required — Tier 2 agents need explicit human approval');

    const toEmail = typeof input.toEmail === 'string' ? input.toEmail.trim() : '';
    const toName = typeof input.toName === 'string' ? input.toName.trim() : 'Sustainability Team';
    const channel = input.channel === 'linkedin' ? 'linkedin' : 'email';

    if (channel === 'email' && !toEmail) {
      throw new Error('toEmail is required for email channel');
    }

    return { threadId, toEmail, toName, channel, approvedBy };
  }

  private async fetchThread(threadId: string): Promise<ThreadRow | null> {
    const supabaseUrl = process.env.SUPABASE_URL;
    const supabaseKey = process.env.SUPABASE_SERVICE_KEY;
    if (!supabaseUrl || !supabaseKey) return null;

    try {
      const res = await fetch(
        `${supabaseUrl}/rest/v1/outreach_threads?id=eq.${encodeURIComponent(threadId)}&select=id,email_subject,email_body,linkedin_message,org_domain,status&limit=1`,
        {
          headers: {
            apikey: supabaseKey,
            Authorization: `Bearer ${supabaseKey}`,
          },
        },
      );
      if (!res.ok) return null;
      const rows = (await res.json()) as ThreadRow[];
      return rows?.[0] || null;
    } catch (err) {
      logger.warn('Failed to fetch thread', { threadId, error: String(err) });
      return null;
    }
  }

  private async sendEmailChannel(
    thread: ThreadRow,
    input: ExecutorInput,
  ): Promise<{ ok: boolean; detail: string }> {
    const html = [
      `<div style="font-family:sans-serif;max-width:600px;line-height:1.6">`,
      thread.email_body
        .split('\n')
        .map((line) => (line.trim() ? `<p>${line}</p>` : '<br>'))
        .join(''),
      `</div>`,
    ].join('');

    const result = await sendEmail({
      from: `${FROM_NAME} <${FROM_EMAIL}>`,
      to: `${input.toName} <${input.toEmail}>`,
      subject: thread.email_subject,
      html,
      text: thread.email_body,
      replyTo: FROM_EMAIL,
      source: 'outreach',
      templateType: 'b2b-outreach',
      metadata: {
        threadId: input.threadId,
        approvedBy: input.approvedBy,
        orgDomain: thread.org_domain,
      },
    });

    return {
      ok: result.ok,
      detail: result.ok
        ? `Delivered via SES (auditId: ${result.auditId || 'n/a'})`
        : result.error || 'SES delivery failed',
    };
  }

  private async queueLinkedInChannel(
    thread: ThreadRow,
    input: ExecutorInput,
    context: AgentContext,
  ): Promise<{ ok: boolean; detail: string }> {
    const supabaseUrl = process.env.SUPABASE_URL;
    const supabaseKey = process.env.SUPABASE_SERVICE_KEY;
    if (!supabaseUrl || !supabaseKey) {
      return { ok: false, detail: 'Supabase not configured — LinkedIn queue unavailable' };
    }

    if (!thread.linkedin_message) {
      return {
        ok: false,
        detail:
          'No LinkedIn message in thread — run outreach-message-crafter with linkedinDraft=true first',
      };
    }

    try {
      const res = await fetch(`${supabaseUrl}/rest/v1/outreach_activities`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: supabaseKey,
          Authorization: `Bearer ${supabaseKey}`,
          Prefer: 'return=minimal',
        },
        body: JSON.stringify({
          thread_id: input.threadId,
          channel: 'linkedin',
          direction: 'outbound',
          outcome: 'queued',
          body: thread.linkedin_message,
          approved_by: input.approvedBy,
          org_id: context.orgId,
          created_at: new Date().toISOString(),
        }),
      });

      if (res.ok || res.status === 201) {
        return {
          ok: true,
          detail: 'LinkedIn message queued — copy from /api/v1/outreach/digest for manual delivery',
        };
      }
      return { ok: false, detail: `LinkedIn queue write failed (HTTP ${res.status})` };
    } catch (err) {
      return { ok: false, detail: `LinkedIn queue error: ${String(err)}` };
    }
  }

  private async updateThreadStatus(threadId: string, status: string): Promise<void> {
    const supabaseUrl = process.env.SUPABASE_URL;
    const supabaseKey = process.env.SUPABASE_SERVICE_KEY;
    if (!supabaseUrl || !supabaseKey) return;

    try {
      await fetch(`${supabaseUrl}/rest/v1/outreach_threads?id=eq.${encodeURIComponent(threadId)}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          apikey: supabaseKey,
          Authorization: `Bearer ${supabaseKey}`,
          Prefer: 'return=minimal',
        },
        body: JSON.stringify({ status, updated_at: new Date().toISOString() }),
      });
    } catch (err) {
      logger.warn('Failed to update thread status', { threadId, error: String(err) });
    }
  }

  private async logActivity(
    input: ExecutorInput,
    thread: ThreadRow,
    result: { ok: boolean; detail: string },
    context: AgentContext,
  ): Promise<void> {
    const supabaseUrl = process.env.SUPABASE_URL;
    const supabaseKey = process.env.SUPABASE_SERVICE_KEY;
    if (!supabaseUrl || !supabaseKey) return;

    try {
      await fetch(`${supabaseUrl}/rest/v1/outreach_activities`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: supabaseKey,
          Authorization: `Bearer ${supabaseKey}`,
          Prefer: 'return=minimal',
        },
        body: JSON.stringify({
          thread_id: input.threadId,
          channel: input.channel,
          direction: 'outbound',
          outcome: result.ok ? 'sent' : 'failed',
          body: input.channel === 'email' ? thread.email_subject : thread.linkedin_message || '',
          approved_by: input.approvedBy,
          delivery_detail: result.detail,
          org_id: context.orgId,
          created_at: new Date().toISOString(),
        }),
      });
    } catch (err) {
      logger.warn('Failed to log outreach activity', { error: String(err) });
    }
  }
}
